INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (40,1,9,NULL,NULL,'Prioritas Nasional 3','Kawasan Pariwisata / Destinasi Pariwisata',NULL,NULL,'Indikasi pembangunan/pengembangan bandar udara pada kawasan pariwisata yang dikaitkan dengan RPJMN 2025–2029 PN 3 (pengembangan pariwisata, ekonomi kreatif, dan infrastruktur). Bandara: Kualanamu, Internasional Yogyakarta, Zainuddin Abdul Madjid, Komodo, Matahora, Perairan Misool (Raja Ampat), dan Domine Eduard Osok.',NULL,NULL,NULL,'bi-airplane-engines',NULL,NULL,1,0,1,0,'{\"focus\":\"Fokus mendukung DPP Borobudur–Yogyakarta–Prambanan, Danau Toba, Labuan Bajo, dan Lombok–Gili Tramena.\"}','2026-08-27 04:31:59','2026-08-27 04:31:59');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (41,1,9,NULL,NULL,'Wilayah Terdepan','Kawasan Perbatasan',NULL,NULL,'Indikasi pembangunan/pengembangan bandar udara di kawasan perbatasan. Bandara: Yuvai Semaring, Long Apung, Kol. Robert Atty Bessing, Kalimarau, dan Nunukan.',NULL,NULL,NULL,'bi-signpost-2',NULL,NULL,2,0,1,0,'{\"note\":\"Pertimbangan teknis: rencana induk bandar udara, RTT sisi udara dan sisi darat, serta kesiapan lahan.\"}','2026-08-27 04:31:59','2026-08-27 04:31:59');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (42,1,9,NULL,NULL,'Dukungan Kawasan Pariwisata','Bandar Udara Perairan Periode 2025–2029',NULL,NULL,'Indikasi pembangunan bandar udara perairan sebagai dukungan kawasan pengembangan pariwisata. Lokasi: Bandar Udara Perairan Sulawesi Selatan, pengembangan seaplane di Maluku dan Maluku Utara, serta Bandar Udara Perairan Misool Selatan.',NULL,NULL,NULL,'bi-water',NULL,NULL,3,0,1,0,'{\"note\":\"Belum ada readiness criteria. Lokasi masih dalam proses kelengkapan administrasi dan justifikasi luasan lahan.\"}','2026-08-27 04:31:59','2026-08-27 04:31:59');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (43,1,9,NULL,NULL,'Fokus Wilayah Papua Selatan','Kawasan Sentra Produksi Pangan / Food Estate',NULL,NULL,'Indikasi pembangunan/pengembangan bandar udara pendukung kawasan sentra produksi pangan dengan fokus wilayah Papua Selatan. Bandara: Kimaam, Wanam, Kepi, Senggo, Bomakia, Korowai Batu, Senggeh, Manggelum, Mindiptanah, Tanah Merah, Bade, Okaba, dan Mopah.',NULL,NULL,NULL,'bi-basket',NULL,NULL,4,0,1,0,'{\"note\":\"Pertimbangan: bandar udara UPBU Ditjen Perhubungan Udara dibandingkan bandar udara/lapangan terbang yang dikelola swasta (PT Djarmaru) atau aset pihak swasta terkait rute perintis Mopah–Wanam.\"}','2026-08-27 04:31:59','2026-08-27 04:31:59');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (44,1,9,NULL,NULL,'KEK & Kawasan Industri','Kawasan Hilirisasi',NULL,NULL,'Indikasi pembangunan/pengembangan bandar udara pendukung hilirisasi. Bandara: Raja Haji Abdullah (KEK Arun Lhokseumawe), Malikussaleh, Singkawang dan Pangsuma (KI Ketapang), serta Morowali (KI Morowali/Morowali Utara).',NULL,NULL,NULL,'bi-buildings',NULL,NULL,5,0,1,0,'{\"focus\":\"Pertimbangan teknis pengembangan memperhatikan: (1) rencana induk bandar udara; (2) RTT sisi udara dan sisi darat; (3) kesiapan lahan.\",\"note\":\"Telah dilakukan penandatanganan kesepakatan bersama pengembangan Bandar Udara Morowali antara Ditjen Perhubungan Udara dan PT Zhenshi Indonesia Industrial Park pada 13 November 2024. Rencana CSR sebesar Rp166.646.566.790 dengan rincian kegiatan: pekerjaan runway 300 m x 30 m; runway strip 260 m x 85 m; RESA 92,5 m x 65 m; serta pagar sisi udara sepanjang 720 meter.\"}','2026-08-27 04:31:59','2026-08-27 04:31:59');
