INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (53,2,16,NULL,NULL,'Tentang Direktorat','Mewujudkan Kebandarudaraan Nasional yang Andal',NULL,NULL,'Direktorat Bandar Udara merupakan salah satu unit teknis di bawah Direktorat Jenderal Perhubungan Udara, Kementerian Perhubungan Republik Indonesia. Direktorat ini bertanggung jawab atas perumusan kebijakan, penyusunan norma, standar, prosedur dan kriteria (NSPK), pemberian bimbingan teknis dan supervisi, serta pemantauan, analisis, evaluasi, dan pelaporan di bidang kebandarudaraan.\n\nDengan cakupan lebih dari 300 bandar udara di 34 provinsi, Direktorat Bandar Udara berperan strategis dalam menjaga keselamatan, keamanan, dan kualitas layanan penerbangan sipil nasional, sekaligus mendorong konektivitas antarwilayah melalui pengembangan prasarana bandar udara yang berkelanjutan.','',NULL,NULL,'bi-building-check','art-6',NULL,0,0,1,0,'{\"visi\":\"\\\"Terwujudnya penyelenggaraan bandar udara yang profesional, aman, dan berkelanjutan guna mendukung konektivitas nasional yang andal dan berdaya saing.\\\"\"}','2026-08-27 04:31:59','2026-08-27 04:32:24');
