INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (191,6,47,NULL,'42-sertifikat-bandar-udara-baru',NULL,'Direktorat Terbitkan 42 Sertifikat Bandar Udara Baru di Triwulan II',NULL,'Proses sertifikasi dipercepat melalui digitalisasi berkas dan verifikasi lapangan terpadu.','Jakarta — Direktorat Bandar Udara mengumumkan penerbitan 42 sertifikat operasi bandar udara baru sepanjang triwulan II tahun 2026. Capaian ini merupakan hasil dari percepatan proses verifikasi berkas dan inspeksi lapangan yang kini didukung sistem informasi layanan digital terpadu.\n\nMenurut catatan internal direktorat, rata-rata waktu penyelesaian layanan sertifikasi menurun dari sebelumnya lebih dari 30 hari kerja menjadi rata-rata 18 hari kerja. Penurunan waktu layanan ini didorong oleh digitalisasi pengajuan berkas serta koordinasi yang lebih efisien antara tim verifikasi dan tim inspeksi lapangan di lima subdirektorat teknis.\n\nSertifikat yang diterbitkan mencakup bandar udara di berbagai wilayah, termasuk sejumlah bandar udara perintis di kawasan timur Indonesia yang selama ini menghadapi tantangan aksesibilitas dalam proses pengajuan layanan. Direktorat menegaskan komitmennya untuk terus memperluas jangkauan layanan digital hingga ke bandar udara di wilayah terpencil.\n\nKe depan, direktorat berencana mengintegrasikan sistem pemantauan pascasertifikasi agar kepatuhan standar keselamatan dapat dipantau secara berkelanjutan, bukan hanya pada saat proses penerbitan sertifikat berlangsung.','',NULL,NULL,'bi-patch-check','art-4','2026-07-14',1,1,1,11,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:38:57');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (192,6,48,NULL,'perluasan-landasan-pacu-perintis',NULL,'Perluasan Landasan Pacu di 6 Bandar Udara Perintis Dimulai',NULL,'Program prasarana tahun ini menyasar bandar udara perintis di kawasan timur Indonesia.','Program perluasan landasan pacu di enam bandar udara perintis resmi dimulai pada awal Juli 2026. Kegiatan ini merupakan bagian dari prioritas pemerataan prasarana bandar udara di wilayah 3T.\n\nPekerjaan mencakup perpanjangan dan pelebaran landas pacu, perbaikan marka, serta peningkatan fasilitas alat bantu visual. Seluruh pekerjaan ditargetkan rampung sebelum akhir tahun anggaran berjalan.','',NULL,NULL,'bi-cone-striped','art-1','2026-07-08',2,1,1,3,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:32:28');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (193,6,49,NULL,'simulasi-tanggap-darurat-pkp-pk',NULL,'Simulasi Tanggap Darurat PKP-PK Digelar Serentak',NULL,'Latihan gabungan bertujuan menguji kesiapan tim penyelamatan bandar udara.','Simulasi tanggap darurat PKP-PK digelar serentak di sejumlah bandar udara untuk menguji kesiapan personel, peralatan, dan koordinasi antarinstansi dalam menghadapi keadaan darurat penerbangan.\n\nLatihan mencakup skenario kecelakaan pesawat udara di area bandar udara, evakuasi penumpang, serta pemadaman kebakaran sesuai standar waktu respons yang berlaku.','',NULL,NULL,'bi-life-preserver','art-5','2026-07-02',3,1,1,3,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:32:28');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (194,6,50,NULL,'konsultasi-publik-standar-keselamatan',NULL,'Konsultasi Publik Standar Keselamatan Landasan Pacu Digelar',NULL,'Direktorat membuka masukan publik atas rancangan standar keselamatan terbaru.','Direktorat Bandar Udara menggelar konsultasi publik atas rancangan standar keselamatan operasional landasan pacu. Kegiatan ini melibatkan penyelenggara bandar udara, akademisi, dan asosiasi penerbangan.\n\nMasukan yang diperoleh akan menjadi bahan penyempurnaan rancangan sebelum ditetapkan sebagai peraturan.','',NULL,NULL,'bi-journal-text','art-3','2026-06-28',4,0,1,3,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:32:28');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (195,6,51,NULL,'kerja-sama-teknis-airnav',NULL,'Kerja Sama Teknis dengan AirNav Perkuat Keselamatan Operasional',NULL,'Kolaborasi difokuskan pada integrasi data pemantauan sisi udara dan sisi darat.','Direktorat Bandar Udara dan AirNav Indonesia menandatangani kerja sama teknis untuk memperkuat keselamatan operasional bandar udara melalui integrasi data pemantauan sisi udara dan sisi darat.\n\nKerja sama ini mencakup pertukaran data operasional, pelatihan bersama, serta pengembangan prosedur koordinasi dalam kondisi darurat.','',NULL,NULL,'bi-people-fill','art-7','2026-06-20',5,0,1,3,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:32:28');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (196,6,52,NULL,'seleksi-tenaga-teknis-2026',NULL,'Pembukaan Seleksi Tenaga Teknis Bandar Udara 2026',NULL,'Pendaftaran dibuka untuk memperkuat kapasitas inspektur keselamatan bandar udara.','Direktorat Bandar Udara membuka seleksi tenaga teknis bandar udara tahun 2026. Formasi yang dibuka meliputi inspektur keselamatan, teknisi prasarana, dan analis data kebandarudaraan.\n\nPendaftaran dilakukan secara daring melalui portal resmi. Seluruh tahapan seleksi tidak dipungut biaya.','',NULL,NULL,'bi-megaphone','art-6','2026-06-15',6,0,1,4,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:32:28');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (197,6,48,NULL,'rehabilitasi-terminal-wilayah-tengah',NULL,'Rehabilitasi Terminal Bandar Udara Wilayah Tengah Rampung 70%',NULL,'Renovasi terminal ditargetkan tuntas sebelum akhir tahun anggaran berjalan.','Progres rehabilitasi terminal penumpang di sejumlah bandar udara wilayah tengah telah mencapai 70 persen. Pekerjaan meliputi perluasan ruang tunggu, pembaruan sistem pendingin, serta peningkatan aksesibilitas bagi penyandang disabilitas.',NULL,NULL,NULL,'bi-building','art-2','2026-06-05',7,0,1,3,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:31:59');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (198,6,49,NULL,'inspeksi-terpadu-kawasan-barat',NULL,'Inspeksi Terpadu Digelar di 12 Bandar Udara Kawasan Barat',NULL,'Inspeksi mencakup pemeriksaan prasarana, peralatan darurat, dan tata kelola operasional.','Tim gabungan Direktorat Bandar Udara melaksanakan inspeksi terpadu di 12 bandar udara kawasan barat Indonesia. Pemeriksaan mencakup kondisi prasarana sisi udara, kesiapan peralatan darurat, serta tata kelola operasional bandar udara.',NULL,NULL,NULL,'bi-clipboard-check','art-8','2026-05-28',8,0,1,3,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:31:59');
INSERT INTO `contents` (`id`, `category_id`, `subcategory_id`, `parent_id`, `slug`, `eyebrow`, `title`, `subtitle`, `excerpt`, `body`, `image`, `file`, `url`, `icon`, `art_class`, `published_at`, `sort`, `is_featured`, `is_active`, `views`, `extra`, `created_at`, `updated_at`) VALUES (199,6,47,NULL,'waktu-layanan-sertifikasi-18-hari',NULL,'Waktu Layanan Sertifikasi Dipangkas Menjadi Rata-Rata 18 Hari',NULL,'Transformasi digital layanan mempercepat proses verifikasi dan penerbitan sertifikat.','Rata-rata waktu layanan sertifikasi bandar udara kini turun menjadi 18 hari kerja. Percepatan ini dicapai melalui digitalisasi pengajuan berkas, verifikasi paralel, serta penjadwalan inspeksi lapangan yang lebih efisien.',NULL,NULL,NULL,'bi-award','art-4','2026-05-19',9,0,1,3,'{\"author\":\"Humas Direktorat Bandar Udara\"}','2026-08-27 04:31:59','2026-08-27 04:31:59');
